
import path = require("path");
import { Stack, Duration } from "aws-cdk-lib";
import { Vpc } from "aws-cdk-lib/aws-ec2";
import { Code, Function, FunctionProps, Runtime } from "aws-cdk-lib/aws-lambda";
import { LambdaProps } from "../domain/stackProps";

export class Lambda {

    public readonly func: Function;

    constructor(stack: Stack, lambdaProps: LambdaProps) {
        this.func = this.createFunction(stack, lambdaProps)
    }
    public createFunction (stack: Stack, lambdaProps: LambdaProps): Function {

        const networkOptions = lambdaProps?.network?.vpc instanceof Vpc
            ? {
                vpc: lambdaProps.network.vpc,
                securityGroups: [lambdaProps.network.securityGroup],
            }
            : {};

        const options: FunctionProps = {
            runtime: Runtime.NODEJS_22_X,
            handler: lambdaProps.codePath,
            code: Code.fromAsset(path.join(__dirname, lambdaProps.folder)),
            timeout: lambdaProps.timeout ?  Duration.seconds(lambdaProps.timeout) :  Duration.seconds(60 * 5),
            environment: lambdaProps.environmentVariables,
            memorySize: lambdaProps.memorySize || 512,
            ...networkOptions,
        };

        const handler = new Function(stack, lambdaProps.name, options);

        return handler;
    }
}